import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());

        int count = 0;
        int value = 665;
        while (count < n) {
            ++value;
            if (String.valueOf(value).contains("666")) {
                ++count;
            }
        }

        System.out.print(value);
    }
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    int count = 0;
    int value = 665;
    while (count < n) {
        ++value;
        if (to_string(value).find("666") != string::npos) {
            ++count;
        }
    }

    cout << value;
    return 0;
}
